from playwright.sync_api import sync_playwright
def ok(n,c): print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_page(viewport={'width':390,'height':844})
    errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto('http://localhost:8123/'); pg.wait_for_selector('.welcome')
    pg.click('[data-act=wz-old]'); pg.click('[data-act=start-empty]'); pg.wait_for_selector('#acct-form'); pg.fill('[name=name]','Wallet'); pg.click('#acct-form .btn'); pg.wait_for_timeout(800)
    J=lambda js: pg.evaluate("(async()=>{const c=await import('/js/core.js');"+js+"})()")
    J("""c.commit(d=>{d.settings.mode='advanced';
      const A=(id,name,cur,ex,w,amt,type)=>{d.accounts.push(c.stamp({id,name,type:type||'crypto',cur,exchange:ex,wallet:w,include:true,invtab:!!ex}));d.txs.push(c.stamp({id:'t'+id,kind:'income',date:c.nowStamp(),acct:id,cur,fx:1,amount:amt,name:'dep',cat:'',items:[],toAcct:'',toAmount:null,fee:0,notes:'',labels:'',flag:null,createdAt:Date.now()}))};
      A('b1','Binance BTC','BTC','Binance','Spot',1);A('b2','Binance USDT','USDT','Binance','Spot',500);A('b3','Binance BTC Earn','BTC','Binance','Earn',2);A('b5','Binance ETH F','ETH','Binance','Futures',3);
      A('y1','Bybit BTC','BTC','Bybit','Spot',0.5);A('y2','Bybit USDT','USDT','Bybit','Spot',300);
      A('j1','SMBC Prestia','JPY','','',100000,'bank');A('j2','PayPay','JPY','','',5000,'ewallet');A('j3','Cash JPY','JPY','','',3000,'cash');A('u1','Wise USD','USD','','',200,'bank')})""")
    # 2 daily averages (Home)
    J("""c.commit(d=>{const acc=d.accounts.find(x=>x.name==='Wallet');const day=n=>{const x=new Date();x.setDate(x.getDate()-n);return x};
      for(const [n,a] of [[0,700],[3,1400],[10,3000],[40,6000]]) d.txs.push(c.stamp({id:'sp'+n,kind:'expense',date:c.nowStamp(day(n)),acct:acc.id,cur:acc.cur,fx:1,amount:a,name:'x'+n,cat:'',items:[],toAcct:'',toAmount:null,fee:0,notes:'',labels:'',flag:null,createdAt:Date.now()}))})""")
    pg.goto('http://localhost:8123/#/home'); pg.wait_for_timeout(1500)
    t=pg.inner_text('.wkavg') if pg.locator('.wkavg').count() else ''; print(repr(t))
    ok('three averages shown', all(x in t for x in ['Last 7 days','Last 30 days','Overall']))
    # expected: 7d=(700+1400)/7=300 ; 30d=(700+1400+3000)/30=170 ; overall=(700+1400+3000+6000)/41 days
    ok('7-day average counts zero days (2,100 / 7 = 300)', '300' in t.split('Last 30')[0])
    ok('30-day average (5,100 / 30 = 170)', '170' in t.split('Last 30')[1].split('Overall')[0])
    ok('overall over 41 calendar days (11,100 / 41 = 270.73)', '270.7' in t.split('Overall')[1] and '41 days' in t)
    # 3 qty
    pg.goto('http://localhost:8123/#/ledger'); pg.wait_for_timeout(600)
    pg.click('.fab'); pg.wait_for_selector('#entry'); pg.wait_for_timeout(300)
    pg.evaluate("document.querySelector('[data-e=items-on]').click()"); pg.wait_for_timeout(300)
    pg.click('.items .item .in-q'); pg.wait_for_timeout(200)
    r=pg.evaluate("(()=>{const q=document.querySelector('.items .item .qty'),i=q.querySelector('.in-q'),n=document.querySelector('.items .item input:not(.in-q)');const a=getComputedStyle(q),c=getComputedStyle(i);return {ow:c.outlineStyle,ow2:c.outlineWidth,bs:c.boxShadow,qb:a.borderTopWidth,qh:q.getBoundingClientRect().height,qo:a.outlineStyle,fb:getComputedStyle(q).borderTopColor,bw:getComputedStyle(q.querySelector('button')).borderTopWidth}})()"); print(r)
    ok('no blue outline on the quantity input', r['ow']=='none' or r['ow2']=='0px'); ok('quantity box has no outline or glow', r['qo']=='none' and r['bs']=='none')
    ok('compact (height <= 46)', r['qh']<=46)
    pg.evaluate("document.querySelectorAll('.sheet,.scrim').forEach(x=>x.remove())")
    # 4 picker tree
    pg.evaluate("(async()=>{(await import('/js/trades.js')).openTrade({platform:'Binance'})})()"); pg.wait_for_selector('#tr'); pg.wait_for_timeout(500)
    pg.evaluate("document.querySelector('#tr select[name=asset]').nextElementSibling.click()"); pg.wait_for_selector('.pk-gh'); pg.wait_for_timeout(200)
    heads=lambda: pg.evaluate("[...document.querySelectorAll('.pk-gh')].filter(h=>h.offsetParent).map(h=>h.dataset.g+'|'+h.getAttribute('aria-expanded'))")
    h=heads(); print(h)
    ok('asset picker starts fully collapsed (only the top level shows)', all(x.endswith('false') for x in h) and any(x.startswith('Cryptocurrency|') for x in h) and len(h)<=2)
    pg.evaluate("document.querySelector('.pk-gh[data-g=Cryptocurrency]').click()"); pg.wait_for_timeout(200); h=heads()
    ok('opening Cryptocurrency shows platforms, still collapsed', any(x.startswith('Cryptocurrency › Binance|false') for x in h) and any(x.startswith('Cryptocurrency › Bybit|false') for x in h))
    pg.evaluate("document.querySelector('.pk-gh[data-g=\"Cryptocurrency › Binance\"]').click()"); pg.wait_for_timeout(200); h=heads()
    ok('opening a platform shows its trading accounts', all(any(x.startswith('Cryptocurrency › Binance › '+w) for x in h) for w in ['Spot','Futures']))
    pg.evaluate("document.querySelector('.pk-gh[data-g=\"Cryptocurrency › Binance › Futures\"]').click()"); pg.wait_for_timeout(200)
    ok('opening the trading account shows assets', pg.evaluate("[...document.querySelectorAll('.pk-opt')].filter(o=>o.offsetParent).some(o=>o.innerText.includes('ETH'))"))
    ok('levels can be shut independently', (pg.evaluate("document.querySelector('.pk-gh[data-g=\"Cryptocurrency › Binance\"]').click()"), pg.wait_for_timeout(200), pg.evaluate("[...document.querySelectorAll('.pk-opt')].filter(o=>o.offsetParent).length")==0)[2])
    pg.evaluate("document.querySelector('.pk-gh[data-g=\"Cryptocurrency › Binance\"]').click()"); pg.wait_for_timeout(200)
    pg.evaluate("[...document.querySelectorAll('.pk-opt')].find(o=>o.offsetParent&&o.innerText.includes('ETH')).click()"); pg.wait_for_timeout(500)
    ok('picked ETH on Futures', 'ETH' in pg.evaluate("document.querySelector('#tr select[name=asset]').selectedOptions[0].textContent"))
    # paid from: crypto and traditional sections
    pg.evaluate("document.querySelector('#tr select[name=cash]').nextElementSibling.click()"); pg.wait_for_selector('.pk-gh'); pg.wait_for_timeout(200)
    h=heads(); print(h); ok('Paid From has both sections, collapsed', any(x.startswith('Cryptocurrency|false') for x in h) and any(x.startswith('Traditional accounts|false') for x in h))
    pg.evaluate("document.querySelector('.pk-gh[data-g=\"Traditional accounts\"]').click()"); pg.wait_for_timeout(200); h=heads()
    ok('currencies listed (JPY, USD, ...)', any('Traditional accounts › JPY' in x for x in h) and any('Traditional accounts › USD' in x for x in h))
    pg.evaluate("document.querySelector('.pk-gh[data-g=\"Traditional accounts › JPY\"]').click()"); pg.wait_for_timeout(200); h=heads()
    ok('categories under the currency (Bank, E-wallet, Cash)', any('› JPY › Bank' in x for x in h) and any('› JPY › Cash' in x for x in h))
    pg.evaluate("document.querySelector('.pk-gh[data-g=\"Traditional accounts › JPY › Bank\"]').click()"); pg.wait_for_timeout(200)
    ok('account under the category', pg.evaluate("[...document.querySelectorAll('.pk-opt')].filter(o=>o.offsetParent).some(o=>o.innerText.includes('SMBC Prestia'))"))
    pg.evaluate("document.querySelector('.pk-q')&&(document.querySelector('.pk-q').value='paypay',document.querySelector('.pk-q').dispatchEvent(new Event('input')))"); pg.wait_for_timeout(200)
    ok('search opens the matching branch', pg.evaluate("[...document.querySelectorAll('.pk-opt')].filter(o=>o.offsetParent).some(o=>o.innerText.includes('PayPay'))"))
    pg.evaluate("[...document.querySelectorAll('.pk-opt')].find(o=>o.offsetParent&&o.innerText.includes('PayPay')).click()"); pg.wait_for_timeout(400)
    ok('picked PayPay', 'PayPay' in pg.evaluate("document.querySelector('#tr select[name=cash]').selectedOptions[0].textContent"))
    ok('sheet does not scroll sideways', pg.evaluate("document.documentElement.scrollWidth<=innerWidth+1"))
    ok('no errors %s'%errs, not errs)
    b.close()
